from decimal import Decimal, InvalidOperation
from typing import Any


def _total_amount_is_positive(record: dict) -> bool:
    value = record.get("TOT_AMT", 0)
    if value is None or value == "":
        return False

    try:
        return Decimal(str(value)) > 0
    except (InvalidOperation, ValueError, TypeError):
        return False


def _account_credit_hold(record: dict, tables: dict) -> Any:
    if "ACCT_ID" not in record:
        return ""

    account_id = record["ACCT_ID"]
    rows = tables.get("ACCT_MASTER", [])

    for row in rows:
        if not isinstance(row, dict):
            continue
        if row.get("DEL_FLG") != "Y" and "ACCT_ID" in row:
            if row["ACCT_ID"] == account_id:
                return row.get("CRED_HOLD", "")

    return ""


def fire(state: str, event: str, record: dict, tables: dict) -> dict:
    new_record = dict(record)
    audits: list[str] = []
    notifies: list[str] = []

    if state == "E" and event == "approve":
        if _total_amount_is_positive(record):
            audits.append("ORD_APPR")
            return {
                "state": "A",
                "record": new_record,
                "audits": audits,
                "notifies": notifies,
                "matched": True,
            }

    elif state == "A" and event == "ship":
        audits.append("ORD_SHIP")
        notifies.append("shipped")
        return {
            "state": "S",
            "record": new_record,
            "audits": audits,
            "notifies": notifies,
            "matched": True,
        }

    elif state == "S" and event == "invoice":
        audits.append("ORD_INV")
        return {
            "state": "I",
            "record": new_record,
            "audits": audits,
            "notifies": notifies,
            "matched": True,
        }

    elif state == "E" and event == "cancel":
        audits.append("ORD_CANC")
        return {
            "state": "X",
            "record": new_record,
            "audits": audits,
            "notifies": notifies,
            "matched": True,
        }

    elif state == "A" and event == "cancel":
        if _account_credit_hold(record, tables) != "Y":
            audits.append("ORD_CANC")
            return {
                "state": "X",
                "record": new_record,
                "audits": audits,
                "notifies": notifies,
                "matched": True,
            }

    elif state == "I" and event == "cancel":
        audits.append("ORD_CANC_INV")
        notifies.append("credit_note")
        return {
            "state": "X",
            "record": new_record,
            "audits": audits,
            "notifies": notifies,
            "matched": True,
        }

    return {
        "state": state,
        "record": new_record,
        "audits": ["WF_NOMATCH"],
        "notifies": [],
        "matched": False,
    }
